  "bool:default-open"?: HelixHeadlessAccordionItem["defaultOpen"];
  /** Initial open state for uncontrolled use, where nothing declared one. */
  "prop:defaultOpen"?: HelixHeadlessAccordionItem["defaultOpen"];
